'use strict';
// A disposable worker runs ONLY JavaScript regenerated by the bundled Blockly
// generators. Python and imported executable source are never evaluated here.
(()=>{
  function workerMain(runProgram){
    let serial=0,steps=0,started=Date.now();const pending=new Map();
    const rpc=(kind,data={})=>new Promise((resolve,reject)=>{const id=++serial;pending.set(id,{resolve,reject});postMessage({id,kind,...data});});
    const sleep=ms=>new Promise(r=>setTimeout(r,ms));
    function context(lane='Main'){
      let blockId=null;
      const ctx={
        async guard(){if(++steps>20000||Date.now()-started>120000)throw Error('ทดลองครบขีดจำกัด 20,000 ขั้น / 2 นาทีแล้ว');await sleep(0);},
        async step(id){blockId=id;await ctx.guard();await rpc('step',{blockId:id,lane});},
        async log(value){postMessage({kind:'log',text:String(value).slice(0,1000),lane});},
        async wait(seconds){if(!Number.isFinite(seconds)||seconds<0||seconds>3600)throw Error('เวลารอต้องเป็น 0–3600 วินาที');await sleep(seconds*1000);},
        async read(topic,field,timeout){if(!Number.isFinite(timeout)||timeout<0||timeout>600)throw Error('เวลารอข้อมูลต้องเป็น 0–600 วินาที');const until=Date.now()+timeout*1000;do{await ctx.guard();const sample=await rpc('read',{topic});if(sample&&Date.now()-sample.receivedAt<2000){let v=sample.data;for(const key of field.split('.'))v=v!=null&&Object.hasOwn(v,key)?v[key]:undefined;if(v!==undefined&&v!==null)return v;}await sleep(30);}while(Date.now()<until);throw Error('ยังไม่มีข้อมูลสด: '+topic+' · '+field);},
        async until(test,timeout){if(!Number.isFinite(timeout)||timeout<0||timeout>600)throw Error('เวลารอเงื่อนไขต้องเป็น 0–600 วินาที');let timer;try{await Promise.race([(async()=>{while(true){if(await test())return;await ctx.guard();await sleep(30);}})(),new Promise((_,reject)=>timer=setTimeout(()=>reject(Error('เงื่อนไขยังไม่เป็นจริงภายในเวลาที่กำหนด')),timeout*1000))]);}finally{clearTimeout(timer);}},
        async publish(topic,msgType,value){const type={'std_msgs/msg/String':'string','std_msgs/msg/Float64':'number','std_msgs/msg/Bool':'boolean'}[msgType];if(!/^\/task_studio\/user\/[A-Za-z_]\w*(\/[A-Za-z_]\w*)*$/.test(topic)||typeof value!==type||(type==='number'&&!Number.isFinite(value))||(type==='string'&&value.length>500))throw Error('ชนิดข้อมูลส่งไม่ตรง หรือ Topic อยู่นอก /task_studio/user/');await rpc('publish',{topic,msgType,value});},
        async move(x,y,yaw,speed,timeout){if(lane!=='Main')throw Error('ห้ามสั่งวิ่งในงานคู่ขนาน');if(![x,y,yaw,speed,timeout].every(Number.isFinite)||Math.abs(x)>100||Math.abs(y)>100||Math.abs(yaw)>180||speed<.01||speed>.2||timeout<1||timeout>600)throw Error('ค่าคำสั่ง ODOM อยู่นอกขอบเขต');await ctx.log('⌖ ทดลอง ODOM ('+x+', '+y+') — ไม่ขยับหุ่นยนต์');},
        async python(){throw Error('บล็อก Python ต้องส่งออกให้ผู้ใหญ่ตรวจและรันใน ROS — เว็บไม่รัน Python และยังไม่ทำบล็อกถัดไป');},
        async ask(text,type){const value=await rpc('ask',{text:String(text),valueType:type});if(value===null)throw Error('ยกเลิกการรับข้อมูล');if(type==='NUMBER'){const n=Number(value);if(!Number.isFinite(n))throw Error('กรุณาป้อนตัวเลข');return n;}return value;},
        async parallel(a,b){if(lane!=='Main')throw Error('ไม่รองรับงานคู่ขนานซ้อนกัน');await Promise.all([a(context('A')),b(context('B'))]);postMessage({kind:'joined',blockId,lane});}
      };return ctx;
    }
    onmessage=async e=>{const m=e.data;if(m.kind==='reply'){const p=pending.get(m.id);if(p){pending.delete(m.id);m.error?p.reject(Error(m.error)):p.resolve(m.value);}return;}if(m.kind!=='start')return;try{await runProgram(context());postMessage({kind:'done'});}catch(error){postMessage({kind:'error',text:String(error.message||error)});}};
  }
  class Preview{
    constructor(notify,read){this.notify=notify;this.read=read;this.workers=new Map();this.bus=new Map();this.queue=[];this.paused=false;this.active=false;this.timer=null;}
    start(units,singleStep=false){
      this.stop(false);this.active=true;this.paused=singleStep;this.bus.clear();
      try{for(const u of units){
        // Parse freshly generated blocks as the Worker's script, NOT eval() or
        // Function(). This works under the unchanged Online/Local CSP (no
        // unsafe-eval); only its existing worker-src blob: permission is used.
        const url=URL.createObjectURL(new Blob(['('+workerMain.toString()+')(async function(ctx){\n"use strict";\n',u.javascript,'\n});'],{type:'text/javascript'}));
        try{const worker=new Worker(url);this.workers.set(u.id,worker);worker.onmessage=e=>this.message(u,worker,e.data);worker.onerror=e=>this.fail(e.message);worker.postMessage({kind:'start'});}finally{URL.revokeObjectURL(url);}
      }this.timer=setTimeout(()=>this.fail('ทดลองครบ 2 นาทีแล้ว กดเล่นใหม่ได้'),120000);}catch(e){this.fail('เริ่มการทดลองไม่สำเร็จ: '+e.message);}
    }
    reply(worker,id,value,error){worker.postMessage({kind:'reply',id,value,error});}
    message(unit,worker,m){if(!this.active||this.workers.get(unit.id)!==worker)return;const event={...m,unit:unit.id,file:unit.file};this.notify(event);
      if(m.kind==='step'){const next=()=>this.reply(worker,m.id,true);if(this.paused)this.queue.push(next);else setTimeout(()=>{if(this.active&&this.workers.get(unit.id)===worker){if(this.paused)this.queue.push(next);else next();}},70);}
      if(m.kind==='read')this.reply(worker,m.id,this.bus.get(m.topic)||this.read(m.topic)||null);
      if(m.kind==='publish'){this.bus.set(m.topic,{state:'received',data:{data:m.value},receivedAt:Date.now()});this.reply(worker,m.id,true);}
      if(m.kind==='ask')this.reply(worker,m.id,prompt(m.text));
      if(m.kind==='error')this.fail(m.text);
      if(m.kind==='done'){worker.terminate();this.workers.delete(unit.id);if(!this.workers.size){this.stop(false);this.notify({kind:'complete'});}}
    }
    fail(text){this.stop(false);this.notify({kind:'failed',text});}
    step(){this.paused=true;this.queue.shift()?.();}
    resume(){this.paused=false;this.queue.splice(0).forEach(fn=>fn());}
    stop(report=true){clearTimeout(this.timer);this.workers.forEach(w=>w.terminate());this.workers.clear();this.queue=[];const was=this.active;this.active=false;if(report&&was)this.notify({kind:'stopped'});}
  }
  window.TaskStudioPreview=Preview;
})();
